// Durable global daily budget. Conditional writes reserve a slot atomically.
async function reserveQuota(env){
 if(!env.BUCKET)throw Error('Proteção de uso indisponível; geração temporariamente bloqueada.');
 const key='ai-quota/'+new Date().toISOString().slice(0,10)+'.json';
 for(let i=0;i<6;i++){
  const old=await env.BUCKET.get(key);const count=old?(await old.json()).count:0;
  if(!Number.isInteger(count)||count<0)throw Error('Contador de uso inválido.');
  if(count>=100)throw Error('Limite diário compartilhado da oficina atingido (100 gerações).');
  const headers=new Headers(old?{'If-Match':old.httpEtag}:{'If-None-Match':'*'});
  const saved=await env.BUCKET.put(key,JSON.stringify({count:count+1}),{onlyIf:headers,httpMetadata:{contentType:'application/json'}});
  if(saved)return;
 }
 throw Error('Há várias gerações simultâneas. Tente novamente em instantes.');
}
