async function imageProxy(raw){let u=safe(raw);let r;for(let i=0;i<4;i++){await checkDNS(u);r=await fetch(u,{redirect:'manual',signal:AbortSignal.timeout(10000)});if(r.status>=300&&r.status<400){u=safe(new URL(r.headers.get('location'),u).href);continue}break}if(!r.ok)throw Error('Imagem indisponível');const type=r.headers.get('content-type')?.split(';')[0];if(!['image/jpeg','image/png','image/webp','image/gif','image/avif'].includes(type))throw Error('Formato de imagem não permitido');const reader=r.body.getReader();let length=0,parts=[];while(true){const x=await reader.read();if(x.done)break;length+=x.value.length;if(length>6000000){await reader.cancel();throw Error('Imagem acima de 6MB')}parts.push(x.value)}const data=new Uint8Array(length);let offset=0;for(const part of parts){data.set(part,offset);offset+=part.length}return new Response(data,{headers:{'Content-Type':type,'Cache-Control':'private, max-age=300','X-Content-Type-Options':'nosniff'}})}
async function speech(request,env){if(!env.OPENAI_API_KEY)return json({error:'Áudio indisponível'},503);const raw=await request.text();if(raw.length>6000)return json({error:'Narração longa demais'},413);const b=JSON.parse(raw);if(b.consent!==true)return json({error:'Autorize o envio da narração à OpenAI.'},400);if(typeof b.text!=='string'||b.text.length<10||b.text.length>3500)return json({error:'Use entre 10 e 3500 caracteres na narração.'},400);try{await reserveQuota(env)}catch(e){return json({error:e.message},429)}const r=await fetch('https://api.openai.com/v1/audio/speech',{method:'POST',headers:{Authorization:'Bearer '+env.OPENAI_API_KEY,'Content-Type':'application/json'},signal:AbortSignal.timeout(90000),body:JSON.stringify({model:'gpt-4o-mini-tts',voice:'coral',input:b.text,response_format:'mp3',instructions:'Leia em português brasileiro, tom jornalístico natural, claro e sóbrio, sem dramatizar. Não acrescente palavras.'})});if(!r.ok)return json({error:'Não foi possível gerar áudio (HTTP '+r.status+').'},502);return new Response(r.body,{headers:{'Content-Type':'audio/mpeg','Cache-Control':'no-store','Content-Disposition':'attachment; filename="narracao-ia.mp3"'}})}
export default {async fetch(request,env){const u=new URL(request.url);if(u.pathname==='/api/speech'){if(request.method!=='POST'||request.headers.get('origin')!==u.origin)return json({error:'Origem/método não autorizado'},403);try{return await speech(request,env)}catch{return json({error:'Falha na geração do áudio'},502)}}if(u.pathname==='/api/image'){if(request.method!=='GET')return json({error:'Use GET'},405);try{return await imageProxy(u.searchParams.get('url'))}catch(e){return json({error:e.message},422)}}if(u.pathname==='/api/followups'||u.pathname==='/api/briefing'){if(request.method!=='POST')return json({error:'Use POST'},405);if(request.headers.get('origin')!==u.origin)return json({error:'Origem não autorizada'},403);try{return await followups(request,env,u.pathname!=='/api/followups'?'briefing':'followups')}catch(e){return json({error:'Não foi possível concluir a geração. Tente novamente.'},502)}}if(u.pathname==='/api/demo'){if(request.method!=='POST')return json({error:'Use POST'},405);if(request.headers.get('origin')!==u.origin)return json({error:'Origem não autorizada'},403);return demo(request,env)}if(u.pathname==='/api/extract'){if(request.method!=='POST')return json({error:'Use POST'},405);if(request.headers.get('origin')!==u.origin)return json({error:'Origem não autorizada'},403);if(Number(request.headers.get('content-length')||0)>3000)return json({error:'Pedido muito grande'},413);try{const raw=await request.text();if(raw.length>3000)return json({error:'Pedido muito grande'},413);const body=JSON.parse(raw);return json(await extract(body.url))}catch(e){return json({error:e.message},422)}}if(request.method!=='GET'&&request.method!=='HEAD')return new Response('Method not allowed',{status:405});const path=u.pathname==='/'?'/index.html':u.pathname;const item=assets[path];if(!item)return new Response('Not found',{status:404});return new Response(request.method==='HEAD'?null:Uint8Array.from(atob(item[1]),c=>c.charCodeAt(0)),{headers:{'Content-Type':item[0],'X-Content-Type-Options':'nosniff'}})}};
